#!/usr/bin/env sage

def bytes_to_long(b):
    return int.from_bytes(b, byteorder='big')

def long_to_bytes(n):
    return n.to_bytes((n.bit_length() + 7) // 8, byteorder='big')

def smart_attack_basic(E, P, Q, p):
    # Convert curve to characteristic 0
    Qp = Zp(p, prec=2)
    E0 = EllipticCurve(Qp, [E.a4(), E.a6()])

    # Get p-adic points
    x_P, y_P = P.xy()
    x_Q, y_Q = Q.xy()

    # Convert to additive notation
    u_P = -Qp(x_P) / Qp(y_P)
    u_Q = -Qp(x_Q) / Qp(y_Q)

    # Compute discrete log
    k = (u_Q/u_P).lift()
    return ZZ(k)

